import heapq

def min_bottleneck_path(n, edges, start, end):
    if start == end:
        return 0
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float("inf")] * n
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u == end:
            return d
        for v, w in graph[u]:
            nd = max(d, w)
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return -1 if dist[end] == float("inf") else dist[end]
This is a modified Dijkstra (minimax path): instead of summing edge weights, relax with max(current_bottleneck, edge_weight) and always pop the smallest bottleneck first from the heap. Runs in O((V + E) log V).

def findMedianSortedArrays(nums1, nums2):
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1
    m, n = len(nums1), len(nums2)
    lo, hi = 0, m
    half = (m + n + 1) // 2

    while lo <= hi:
        i = (lo + hi) // 2
        j = half - i
        left1 = nums1[i - 1] if i > 0 else float("-inf")
        right1 = nums1[i] if i < m else float("inf")
        left2 = nums2[j - 1] if j > 0 else float("-inf")
        right2 = nums2[j] if j < n else float("inf")

        if left1 <= right2 and left2 <= right1:
            if (m + n) % 2 == 0:
                return (max(left1, left2) + min(right1, right2)) / 2
            return float(max(left1, left2))
        elif left1 > right2:
            hi = i - 1
        else:
            lo = i + 1
Binary search on the smaller array for a partition index i (and the matching j = half - i on the other array) such that everything left of the partition is <= everything right of it. That gives O(log(min(m, n))), which satisfies the O(log(m+n)) bound.

def longestPalindrome(s):
    if not s:
        return ""
    start, end = 0, 0

    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1

    for i in range(len(s)):
        l1, r1 = expand(i, i)
        if r1 - l1 > end - start:
            start, end = l1, r1
        l2, r2 = expand(i, i + 1)
        if r2 - l2 > end - start:
            start, end = l2, r2

    return s[start:end + 1]
Expand-around-center: every palindrome has a center (a single character for odd length, a gap between two characters for even length), so try both center types at each index and keep the widest match. O(n^2) time, O(1) extra space.

def convert(s, numRows):
    if numRows == 1 or numRows >= len(s):
        return s

    rows = [""] * numRows
    cur_row = 0
    going_down = False

    for c in s:
        rows[cur_row] += c
        if cur_row == 0 or cur_row == numRows - 1:
            going_down = not going_down
        cur_row += 1 if going_down else -1

    return "".join(rows)
Simulate the zigzag directly: walk down rows 0..numRows-1, bounce back up at the edges, appending each character to its current row's buffer, then concatenate all rows. O(n) time, O(n) space.

def twoSum(nums, target):
    seen = {}
    for i, n in enumerate(nums):
        complement = target - n
        if complement in seen:
            return [seen[complement], i]
        seen[n] = i
    return []
Single pass with a hash map from value to index: for each number, check whether its complement was already seen. O(n) time, O(n) space, versus O(n^2) for the brute-force double loop.

def isValid(s):
    stack = []
    pairs = {")": "(", "]": "[", "}": "{"}
    for c in s:
        if c in "([{":
            stack.append(c)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
    return not stack
Push opening brackets onto a stack; on a closing bracket, it must match the top of the stack (the most recent unmatched opener). If the stack is empty at a closing bracket, or non-empty at the end, the string is invalid. O(n) time, O(n) space.

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def reverseList(head):
    prev = None
    while head:
        nxt = head.next
        head.next = prev
        prev = head
        head = nxt
    return prev
Iterative pointer-reversal: at each node, save the next node before overwriting head.next to point backwards, then advance both prev and head. O(n) time, O(1) extra space (versus O(n) call-stack space for a recursive version).

from collections import deque

def levelOrder(root):
    if not root:
        return []
    result = []
    queue = deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(level)
    return result
Standard BFS with a queue: snapshot the queue's current length before the inner loop so each iteration processes exactly one level's worth of nodes before moving to the next. O(n) time, O(n) space.

import heapq

def findKthLargest(nums, k):
    heap = []
    for n in nums:
        heapq.heappush(heap, n)
        if len(heap) > k:
            heapq.heappop(heap)
    return heap[0]
Maintain a min-heap of size k: push every number, and whenever the heap exceeds size k, pop the smallest. After processing all numbers, the heap's smallest element (the root) is the kth largest overall. O(n log k) time, better than the O(n log n) full sort for small k.

def hasCycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False
Floyd's cycle detection (tortoise and hare): the fast pointer moves twice as fast as the slow one. If there's a cycle, the fast pointer eventually laps the slow one and they meet inside the loop; if the list ends, fast hits None first. O(n) time, O(1) space.

def merge(intervals):
    intervals.sort(key=lambda x: x[0])
    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged
Sort by start time first, then sweep once: if the current interval's start is <= the last merged interval's end, they overlap, so extend the last interval's end; otherwise start a new interval. O(n log n) time, dominated by the sort.

def lengthOfLongestSubstring(s):
    last_seen = {}
    start = 0
    best = 0
    for i, c in enumerate(s):
        if c in last_seen and last_seen[c] >= start:
            start = last_seen[c] + 1
        last_seen[c] = i
        best = max(best, i - start + 1)
    return best
Sliding window: track the last index each character was seen at. When a repeat is found inside the current window, jump the window's start past the previous occurrence instead of shrinking it one step at a time. O(n) time, O(min(n, charset size)) space.

import time
import functools

def timed(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            return func(*args, **kwargs)
        finally:
            elapsed = time.perf_counter() - start
            print(f"{func.__name__} took {elapsed:.4f}s")
    return wrapper
functools.wraps copies __name__, __doc__, and other metadata from the wrapped function onto the wrapper, so introspection, help(), and stack traces still show the original function's identity instead of "wrapper".

def paginate(fetch_page):
    page = 1
    while True:
        items = fetch_page(page)
        if not items:
            return
        yield from items
        page += 1
fetch_page(page) returns one page's items at a time; yield from streams them one at a time to the caller, and the generator stops as soon as a page comes back empty. Callers can iterate with a plain for loop instead of materializing every page into a list first, which matters when the API has thousands of pages.

